// src/paginas/Auth/Login.jsx
import { useState } from "react";
import { useAuth } from "../../contexto/AuthContext";

export default function Login() {
  const { login } = useAuth();
  const [identifier, setIdentifier] = useState(""); // email
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  async function onSubmit(e) {
    e.preventDefault();
    setErrorMsg("");
    setLoading(true);
    try {
      await login({ identifier, password });
      // Redirige al dashboard de Admin (lo que uses por defecto)
      window.location.href = "/alumnos";
    } catch (err) {
      const msg = err?.response?.data?.message || "Credenciales inválidas";
      setErrorMsg(msg);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="container d-flex align-items-center justify-content-center" style={{ minHeight: "100vh" }}>
      <div className="card shadow" style={{ maxWidth: 420, width: "100%" }}>
        <div className="card-body p-4">
          <h4 className="mb-3 text-center">Ingreso (Admin)</h4>
          {errorMsg && <div className="alert alert-danger">{errorMsg}</div>}
          <form onSubmit={onSubmit}>
            <div className="mb-3">
              <label className="form-label">Email</label>
              <input
                type="email"
                className="form-control"
                value={identifier}
                onChange={(e) => setIdentifier(e.target.value)}
                placeholder="admin@colegio.cl"
                required
                autoFocus
              />
            </div>
            <div className="mb-3">
              <label className="form-label">Contraseña</label>
              <input
                type="password"
                className="form-control"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>
            <button className="btn btn-primary w-100" disabled={loading}>
              {loading ? "Ingresando..." : "Ingresar"}
            </button>
          </form>
          <p className="text-muted small mt-3">
            * El acceso de administración permite crear cursos, alumnos, etc.
          </p>
        </div>
      </div>
    </div>
  );
}
